import {Localizer,wrap} from './localization.js';
import {MultiSourceLocalizer,Tracker} from './tracking.js';
import {FS,H,Scene,Beamformer,Timer,now,bytes} from './array-dsp.js';
export class ArrayEngine {
 constructor(neural=null){this.timer=new Timer();this.scene=new Scene();this.beam=new Beamformer(this.timer);this.neural=neural;this.mics=Array.from({length:4},()=>new Float32Array(H));this.out=[new Float32Array(H),new Float32Array(H)];this.localizer=new Localizer();this.multi=new MultiSourceLocalizer(this.localizer);this.tracker=new Tracker();this.steeringMode='manual';this.manualSteer=0;this.beam.onSpectrum=(xr,xi)=>{if(this.beam.calFrames>0)return;let t=now();let update=this.localizer.process(xr,xi);this.timer.add('localization SRP-PHAT',t);if(update&&this.steeringMode==='estimated'&&this.localizer.valid&&this.localizer.confidence>=.02){if(this.beam.angle!==this.localizer.direction)this.beam.configure({angle:this.localizer.direction});}
 // Tracked mode: time-frequency voting + multi-target tracker; steering quantized to 1 degree.
 if(this.steeringMode==='tracked'){t=now();if(this.multi.process(xr,xi)){const a=this.tracker.update(this.multi.peaks);if(a!==null&&Math.round(a)!==this.beam.angle)this.beam.configure({angle:Math.round(a)});}this.timer.add('tracking (TF voting + tracker)',t);}};this.enabled=false;this.gain=0;this.volume=-24;this.block=0;this.peak=0;this.overruns=0;this.totalMs=0;this.timedBlocks=0;this.beam.calibrate();}
 lockTarget(world){this.tracker.lock(wrap(world-this.scene.head));}
 configure(c){const was=this.steeringMode;if(c.steeringMode!==undefined)this.steeringMode=c.steeringMode;if(c.trackPolicy!==undefined)this.tracker.configure({policy:c.trackPolicy});if(c.doaChannels!==undefined&&c.doaChannels!==this.localizer.channels){this.multi.reset();this.tracker.reset();}if(c.steer!==undefined)this.manualSteer=c.steer;this.scene.configure(c);this.localizer.configure({channels:c.doaChannels,sector:c.doaSector,anchor:this.manualSteer-this.scene.head});this.beam.configure({method:c.method,angle:this.steeringMode==='manual'?this.manualSteer-this.scene.head:undefined,loading:c.loading});if(this.steeringMode==='tracked'&&was!=='tracked'){this.multi.reset();this.tracker.reset();if(this.tracker.policy==='lock')this.lockTarget(this.manualSteer);}if(c.neural!==undefined&&c.neural!==this.enabled){this.enabled=c.neural;this.neural?.reset();}if(c.volume!==undefined)this.volume=c.volume;}
 process(l,r){let total=now(),t=now();this.scene.process(this.mics,this.beam.calFrames>0);this.timer.add('scene renderer',t);this.beam.process(this.mics,this.out);if(this.enabled&&this.neural){t=now();this.neural.process(this.out);this.timer.add('RNNoise ×2 (including framing)',t);}t=now();let target=10**(this.volume/20);this.peak=0;for(let i=0;i<H;i++){this.gain+=.001*(target-this.gain);l[i]=Math.max(-.89,Math.min(.89,this.out[0][i]*this.gain));r[i]=Math.max(-.89,Math.min(.89,this.out[1][i]*this.gain));this.peak=Math.max(this.peak,Math.abs(l[i]),Math.abs(r[i]));}this.timer.add('level + digital ceiling',t);this.timer.add('total audio block',total);const elapsed=this.timer.last['total audio block'];if(Number.isFinite(elapsed)){this.totalMs+=elapsed;this.timedBlocks++;if(elapsed>H/FS*1000)this.overruns++;}this.block++;}
 report(){const tr=this.steeringMode==='tracked'?this.tracker.report():null;if(tr){tr.head_deg=this.scene.head;}
 return {localization:{...this.localizer.report(),steering_mode:this.steeringMode,applied_direction_world_deg:wrap(this.beam.angle+this.scene.head),tracking:tr},timings:this.timer.report(),memory:{localization_numeric_bytes:bytes(this.localizer),tracking_numeric_bytes:bytes({cr:this.multi.cr,ci:this.multi.ci,hist:this.multi.hist,smooth:this.multi.smooth,score:this.multi.score}),scene_state_bytes:bytes(this.scene.hist),source_PCM_bytes:bytes(this.scene.sources),beamformer_numeric_bytes:bytes({history:this.beam.history,xr:this.beam.xr,xi:this.beam.xi,yr:this.beam.yr,yi:this.beam.yi,ola:this.beam.ola,window:this.beam.window,rr:this.beam.rr,ri:this.beam.ri,dr:this.beam.dr,di:this.beam.di,qr:this.beam.qr,qi:this.beam.qi,ar:this.beam.ar,ai:this.beam.ai,br:this.beam.br,bi:this.beam.bi,wr:this.beam.wr,wi:this.beam.wi,fft:this.beam.fft}),io_numeric_bytes:bytes([this.mics,this.out]),neural_adapter_bytes:this.neural?bytes([this.neural.input,this.neural.output]):0,wasm_heap_reserved_bytes:this.neural?.module.HEAPF32.buffer.byteLength??0,profiling_numeric_bytes:bytes(this.timer)},calibration_remaining_ms:this.beam.calFrames*H/FS*1000,noise_frames:this.beam.noiseFrames,fallback_bins:this.beam.fallbacks,overruns:this.overruns,timed_blocks:this.timedBlocks,rtf:this.timedBlocks?this.totalMs/(this.timedBlocks*H/FS*1000):null,peak:this.peak,algorithmic_delay_ms:512/FS*1000+(this.enabled?30:0),neural:this.enabled};}
}
